(()=>{const allowed=new Set(["Noto Kufi Arabic","Tajawal","Cairo","Noto Naskh Arabic","Alexandria"]);fetch("api/content.php",{credentials:"same-origin"}).then(r=>r.ok?r.json():null).then(result=>{const content=result?.content;if(!content)return;const settings=content.settings||{},heading=allowed.has(settings.arabicHeadingFont)?settings.arabicHeadingFont:"Noto Kufi Arabic",body=allowed.has(settings.arabicBodyFont)?settings.arabicBodyFont:"Tajawal";document.documentElement.style.setProperty("--arabic-heading",`"${heading}",sans-serif`);document.documentElement.style.setProperty("--arabic-body",`"${body}",sans-serif`);window.NUZHA_SERVER_CONTENT=content;window.dispatchEvent(new CustomEvent("nuzha:content",{detail:content}))}).catch(()=>{})})();
